from pathlib import Path
import hashlib,json
F=Path(__file__).resolve().parent
p=F/'freeze_package_v2.py'
s=p.read_text().replace("read(F / 'freeze-v2-exit.json')", "read(F / 'freeze-v3-exit.json')")
s=s.replace("assert changes['all_prior_selected_names_retained']", "assert changes['all_prior_selected_public_names_retained']\nassert not changes['all_prior_selected_names_retained']\nassert changes['exact_removed_private_helper'] == receipt['removed_private_helper']")
s=s.replace("All their public names remain present;", "All their public names remain present. The sole removed eligible constant is the exact private `termV` ParserDescr generated by the replaced source wrapper's local notation; its original source span, record and hash are preserved in `removed-private-notation.json`. Every other prior selected constant is required; ")
s=s.replace("The second parser/archive run exited 0.", "The second parser run exited 1 at an overbroad all-eligible-names retention assertion: it found only that private source notation helper. After root independently confirmed its intentional removal, the third parser/archive run required every other old name and exited 0. The exact 560-record parser result is cached with its parser/raw pins to avoid repeating the expensive parse.")
with (F/'freeze_package_v3.py').open('x',encoding='utf-8',newline='\n') as out:out.write(s)
sha=lambda path:hashlib.sha256(path.read_bytes()).hexdigest()
with (F/'package-v3-derivation.json').open('x',encoding='utf-8',newline='\n') as out:json.dump({'parent':{'path':p.name,'sha256':sha(p)},'derived':{'path':'freeze_package_v3.py','sha256':sha(F/'freeze_package_v3.py')},'changes':['Bind actual third freeze attempt','Require exact public-name retention and hash-bound sole private notation removal','Accurately preserve both actual failures and root-reviewed narrow repair']},out,indent=2);out.write('\n')
print(sha(F/'freeze_package_v3.py'))
